  const avatar = a => S.heads.get(a?.id)||defaultHead();
  function toast(text,kind='') { if(kind==='err')sound('error'); const e=document.createElement('div');const body=$$('.modal-bg .mb').at(-1);e.className=(body?'modal-feedback ':'toast ')+kind;e.setAttribute('role',kind==='err'?'alert':'status');e.textContent=text;if(body){$('.modal-feedback',body)?.remove();body.prepend(e);body.scrollTop=0;}else $('#toasts').append(e);setTimeout(()=>e.remove(),kind==='err'?9000:4500); }
  function bind(selector,fn,root=document,event='click') { const e=$(selector,root);if(e)e.addEventListener(event,async ev=>{try { await fn(ev); }catch(e){toast(e.message||String(e),'err');}}); }
  async function busy(el,fn,text='Подождите…') { const old=el.innerHTML;el.disabled=true;el.textContent=text;try{return await fn();}finally{if(el.isConnected){el.disabled=false;el.innerHTML=old;}} }
  async function settings(patch) { S.settings=await call('saveSettings',patch);applyAppearance();renderBar();renderAccountCard(); }
  async function refreshInstances() { S.instances=await call('getInstances');S.settings=await call('getSettings');renderBar(); }
  async function refreshAccounts() { S.accounts=await call('getAccounts');S.settings=await call('getSettings');renderAccountCard();renderBar();loadHeads(); }
  async function loadHeads() { for(const a of S.accounts){try{const b=await call('getSkin',a.id);if(b)S.heads.set(a.id,Skin.headDataUrl(await Skin.toCanvas64(b)));}catch{}}renderAccountCard();if(S.page==='accounts')renderAccounts(); }
  const modalStack=[];
  function modal(title,content,actions=[],wide=false) {
    const opener=document.activeElement,bg=document.createElement('div');bg.className='modal-bg';$('#toasts').replaceChildren();
    bg.innerHTML=`<div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="mh"><h3>${esc(title)}</h3><button class="btn icon ghost x" aria-label="Закрыть">${icon('close')}</button></div><div class="mb">${content}</div><div class="mf"></div></div>`;
    document.body.append(bg);const m={root:bg,body:$('.mb',bg),q:s=>$(s,bg),close:()=>{bg.remove();modalStack.splice(modalStack.indexOf(m),1);opener?.focus();}};
    modalStack.push(m);bind('.x',m.close,bg);bg.addEventListener('mousedown',e=>{if(e.target===bg)m.close();});
    for(const a of actions){const b=document.createElement('button');b.className='btn '+(a.primary?'primary ':'')+(a.danger?'danger':'');b.textContent=a.text;$('.mf',bg).append(b);b.addEventListener('click',async()=>{try{await busy(b,()=>a.run(m,b));}catch(e){toast(e.message,'err');}});}
    setTimeout(()=>($('input:not([type=checkbox]),textarea,select',bg)||$('.x',bg))?.focus(),30);
    bg.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT'&&e.target.type!=='checkbox'){const buttons=$$('.mf button',bg);if(buttons.length){e.preventDefault();buttons.at(-1).click();}}if(e.key==='Tab'){const f=$$('button,input,select,textarea,[tabindex="0"]',bg).filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
    return m;
  }
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){modalStack.at(-1)?.close();$('.ctx')?.remove();}});
  async function confirm(title,text,run,danger=false) { modal(title,`<p>${esc(text)}</p>`,[{text:'Отмена',run:m=>m.close()},{text:danger?'Удалить':'Продолжить',primary:!danger,danger,run:async m=>{await run();m.close();}}]); }
  function textPrompt(title,label,value,run) { modal(title,`<label class="field">${esc(label)}<input class="input" id="promptValue" value="${esc(value)}" maxlength="200"></label>`,[{text:'Отмена',run:m=>m.close()},{text:'Сохранить',primary:true,run:async m=>{const v=m.q('#promptValue').value.trim();if(!v)throw new Error('Введите значение');await run(v);m.close();}}]); }
  const pages=[['home','Главная','home'],['instances','Мои сборки','box'],['modpacks','Каталог сборок','download'],['mods','Моды и ресурсы','mods'],['skins','Редактор скинов','skin'],['files','Файлы сборки','folder'],['news','Новости','news'],['accounts','Аккаунты','user'],['settings','Настройки','settings'],['shop','Fox Store','box'],['subscription','Моя подписка','lock'],['wallet','Кошелёк','box'],['friends','Друзья','user'],['support','Поддержка','news'],['tutorial','Обучение','clock'],['v3-tools','Инструменты v3','settings'],['profile-settings','Профиль и приватность','settings'],['players','Профили игроков','user'],['achievements','Задания и достижения','clock'],['leaderboards','Топ игроков','user']];
  $('#nav').innerHTML=pages.map(([id,label,ic],i)=>`${i===6?'<div class="sep"></div>':''}<button data-page="${id}" title="${label}">${icon(ic)}<span class="nav-label">${label}</span></button>`).join('');
