    const functions={home:renderHome,instances:renderInstances,modpacks:renderModpacks,mods:renderMods,skins:renderSkins,files:renderFiles,news:renderNews,accounts:renderAccounts,settings:renderSettings,admin:renderAdmin,wallet:renderWallet,friends:renderFriends,support:()=>renderSupport(false),tutorial:renderTutorial,'v3-tools':renderV3Tools,work:()=>renderSupport(true),control:renderControl,'profile-settings':renderProfileSettings,shop:renderShop,subscription:renderSubscription,players:renderPlayers,achievements:renderAchievements,quests:renderQuests,leaderboards:renderLeaderboards};
    Promise.resolve().then(()=>functions[page]()).catch(e=>toast(e.message,'err'));
