  function renderAccountCard(){const a=account();$('#accCard').classList.toggle('pumpkin-frame',S.cloud?.club_version===2?S.cloud?.profile?.equipped_cosmetic==='pumpkin-frame':!!S.cloud?.purchases?.some(p=>p.product_id==='pumpkin-frame'));const cosmetic=cosmeticInfo(S.cloud?.profile?.equipped_cosmetic);$('#accCard').dataset.cosmetic=cosmetic?S.cloud.profile.equipped_cosmetic:'';const tier=Math.max(0,...(S.cloud?.purchases||[]).filter(p=>Date.parse(p.expires_at)>Date.now()).map(p=>S.cloud?.catalog?.find(c=>c.id===p.product_id)?.tier||0));$('#accCard').innerHTML=`<img class="head" src="${avatar(a)}" alt=""><div class="meta"><b>${esc(a?.name||'Добавить аккаунт')}</b><small>${tier?['','Fox Plus','Fox Pro','Fox Exclusive'][tier]:a?(a.type==='microsoft'?'Microsoft · лицензия':'Офлайн-аккаунт'):'Начни своё приключение'}</small></div>${cosmetic?`<span class="profile-accessory" title="${esc(cosmetic.label)} · только Fox Launcher">${cosmetic.symbol}</span>`:''}${icon('down')}`;}
  bind('#accCard',()=>nav('accounts'));
