  function renderAccounts(){const e=$('#page-accounts');e.innerHTML=head('Аккаунты','Выбери аккаунт для запуска игры.')+`<div class="login-opts"><div class="login-opt"><h4><span class="ms-logo"><i style="background:#f35325"></i><i style="background:#81bc06"></i><i style="background:#05a6f0"></i><i style="background:#ffba08"></i></span>Microsoft</h4><p>Для лицензии Minecraft Java Edition. Вход проходит на странице Microsoft. Пароль лаунчер не получает.</p>${btn('msLogin','Войти через Microsoft','user','primary')}</div><div class="login-opt"><h4>${icon('user')}Офлайн-аккаунт</h4><p>Для одиночной игры и серверов, допускающих офлайн-аккаунты. Не даёт лицензию и не подходит для серверов с проверкой Microsoft.</p><div class="row"><input id="offlineName" class="input" placeholder="Твой ник" maxlength="16" style="flex:1">${btn('offlineAdd','Добавить','plus')}</div></div></div><div class="section-title"><h3>Сохранённые аккаунты</h3></div><div class="acc-list">${S.accounts.length?S.accounts.map(a=>`<div class="acc ${account()?.id===a.id?'on':''}" data-acc="${esc(a.id)}"><img src="${avatar(a)}" alt=""><div class="l"><b>${esc(a.name)}</b><div class="muted">${a.type==='microsoft'?'Microsoft · лицензия':'Офлайн'}</div></div><button class="btn sm ${account()?.id===a.id?'ghost':'primary'}" data-accact="select">${account()?.id===a.id?'Выбран ✓':'Выбрать'}</button><button class="btn sm icon ghost danger" data-accact="remove" title="Удалить из лаунчера">${icon('trash')}</button></div>`).join(''):empty('Добавь аккаунт, чтобы начать','user')}</div>`;
    renderFoxAccount(e).catch(err=>toast(err.message,'err'));
    bind('#offlineAdd',ev=>busy(ev.currentTarget,async()=>{await call('addOffline',$('#offlineName',e).value.trim());await refreshAccounts();renderAccounts();toast('Аккаунт добавлен','ok');}),e);bind('#offlineName',ev=>{if(ev.key==='Enter')$('#offlineAdd',e).click();},e,'keydown');bind('#msLogin',ev=>busy(ev.currentTarget,async()=>{await call('loginMicrosoft');await refreshAccounts();renderAccounts();toast('Вход выполнен','ok');},'Ожидание входа…'),e);$$('[data-acc]',e).forEach(row=>{const a=S.accounts.find(a=>a.id===row.dataset.acc);bind('[data-accact=select]',async()=>{await settings({selectedAccount:a.id});renderAccounts();},row);bind('[data-accact=remove]',()=>confirm('Удалить аккаунт из лаунчера?',a.name+' — будет удалена только локальная запись. Аккаунт Microsoft останется.',async()=>{await call('removeAccount',a.id);await refreshAccounts();renderAccounts();},true),row);});
  }
  // --------- настройки ---------
  async function renderSettings(){const e=$('#page-settings'),s=S.settings,max=Math.max(1024,Math.floor((S.info.totalMem-1024)/256)*256);e.innerHTML=head('Настройки','Общие параметры применяются ко всем сборкам.',btn('saveSettings','Сохранить','check','primary'))+`<div class="set-group"><h3>Внешний вид</h3><div class="set-item"><div class="l"><b>Основной цвет интерфейса</b><small>Меняет акцент и кнопку «Играть». Цвет сборок настраивается отдельно.</small></div><input type="color" id="accentColor" value="${/^#[\da-f]{6}$/i.test(s.accent)?s.accent:'#ff7a1a'}" aria-label="Цвет интерфейса"></div></div><div class="set-group"><h3>Производительность</h3><div class="set-item"><div class="l"><b>Оперативная память</b><small>Всего ${Math.round(S.info.totalMem/1024)} ГБ. Не выделяй игре всю память компьютера.</small></div><b id="ramLabel">${s.memory} МБ</b></div><div class="set-item"><input type="range" id="memory" min="512" max="${max}" step="256" value="${s.memory}"></div><div class="set-item"><label class="field" style="width:100%">Аргументы JVM<input class="input" id="jvmArgs" value="${esc(s.jvmArgs)}" placeholder="-XX:+UseG1GC"></label></div></div><div class="set-group"><h3>Java</h3><div class="set-item"><div class="l"><b>Автоматический подбор</b><small>Перед запуском проверяется нужная версия Java. Если её нет, лаунчер загрузит Temurin.</small></div>${btn('javaRefresh','Найти Java','refresh','sm')}</div><div class="set-item"><input class="input" id="javaPath" value="${esc(s.javaPath)}" placeholder="Автоматически (рекомендуется)" style="flex:1">${btn('javaPick','Выбрать…','folder','sm')}${btn('javaAuto','Авто','','sm')}</div><div class="java-list" id="javaList"><div class="dim">Нажми «Найти Java», чтобы проверить установленные версии.</div></div><div class="set-item"><div class="l"><b>Загрузить вручную</b><small>Java 8 — старые версии, 17 — 1.18–1.20.4, 21 — 1.20.5–1.21.x. Для новых версий требования берутся из метаданных.</small></div><select class="input" id="javaMajor">${[8,17,21,25].map(n=>`<option value="${n}" ${n===21?'selected':''}>Java ${n}</option>`).join('')}</select>${btn('javaDownload','Загрузить','download','sm')}</div></div><div class="set-group"><h3>Окно и запуск</h3><div class="set-item"><div class="l"><b>Разрешение окна</b><small>0 × 0 — размер по умолчанию</small></div><input type="number" class="input" id="winWidth" value="${s.width}" min="0" max="7680" style="width:100px"><span>×</span><input type="number" class="input" id="winHeight" value="${s.height}" min="0" max="4320" style="width:100px"></div>${[['closeOnLaunch','Скрывать лаунчер во время игры','После выхода из игры лаунчер появится снова.'],['showConsoleOnLaunch','Показывать консоль при запуске','Полезно для поиска проблем с модами.']].map(([k,t,d])=>`<div class="set-item"><div class="l"><b>${t}</b><small>${d}</small></div><label class="switch"><input id="${k}" type="checkbox" ${s[k]?'checked':''}><span></span></label></div>`).join('')}</div><div class="set-group"><h3>Fox Launcher ${esc(S.info.version||'1.0.0')}</h3><div class="set-item"><div class="l"><b>Папка данных</b><small class="selectable">${esc(S.info.root)}</small></div>${btn('openRoot','Открыть','folder','sm')}</div><div class="set-item"><div class="l"><small>Независимый проект. Не связан с Mojang или Microsoft. Поддерживаются Vanilla, Fabric, Quilt и NeoForge.</small></div></div></div>`;
    bind('#memory',ev=>$('#ramLabel',e).textContent=ev.target.value+' МБ',e,'input');bind('#javaAuto',()=>$('#javaPath',e).value='',e);bind('#javaPick',async()=>{const j=await call('pickJava');if(j)$('#javaPath',e).value=j.path;else toast('Java не выбрана или не удалось определить её версию');},e);bind('#openRoot',()=>call('openRoot'),e);
    async function findJava(){const box=$('#javaList',e);box.innerHTML='<div class="spinner"></div>';try{const list=await call('findJavas');box.innerHTML=list.length?list.map((j,n)=>`<div class="java-item"><span class="tag ${j.managed?'accent':''}">Java ${j.major}</span><b>${esc(j.version)}</b><code title="${esc(j.path)}">${esc(j.path)}</code><button class="btn sm ghost" data-javapick="${n}">Выбрать</button></div>`).join(''):'<div class="dim">Java не найдена. Она загрузится при первом запуске.</div>';$$('[data-javapick]',box).forEach(b=>b.onclick=()=>$('#javaPath',e).value=list[+b.dataset.javapick].path);}catch(err){box.textContent=err.message;}}
    bind('#javaRefresh',ev=>busy(ev.currentTarget,findJava),e);bind('#javaDownload',ev=>busy(ev.currentTarget,async()=>{const n=+$('#javaMajor',e).value;await call('downloadJava',n);toast('Java '+n+' установлена','ok');$('#progTxt').textContent='Java установлена';await findJava();}),e);
    bind('#saveSettings',ev=>busy(ev.currentTarget,async()=>{const w=+$('#winWidth',e).value,h=+$('#winHeight',e).value,url=s.newsFeedUrl||'';if((w===0)!==(h===0)||w<0||h<0||w>7680||h>4320)throw new Error('Укажи оба размера окна или 0 × 0');if(url&&!safeUrl(url))throw new Error('Лента должна использовать HTTPS');await settings({memory:+$('#memory',e).value,jvmArgs:$('#jvmArgs',e).value,javaPath:$('#javaPath',e).value.trim(),width:w,height:h,closeOnLaunch:$('#closeOnLaunch',e).checked,showConsoleOnLaunch:$('#showConsoleOnLaunch',e).checked,newsFeedUrl:url,accent:$('#accentColor',e).value});toast('Настройки сохранены','ok');loadNews().catch(()=>{});}),e);
    await extraSettings(e);
  }
  // --------- редактор новостей (пароль проверяется в главном процессе) ---------
  async function adminCall(m,...args){try{return await call(m,S.admin?.token,...args);}catch(e){if(/сессия|заново/i.test(e.message)){S.admin=null;if(S.page==='admin')renderAdmin();}throw e;}}
  async function renderAdmin(){const e=$('#page-admin');if(!S.admin||Date.now()>S.admin.expires){S.admin=null;e.innerHTML=head('Админ-панель','Публикация новостей Fox Launcher.')+`<div class="admin-login card col"><div class="admin-lock">${icon('lock')}</div><h2>Вход в редактор новостей</h2><p class="muted">Пароль защищает локальный редактор. Глобальные операции дополнительно требуют Fox ID владельца; скрытая кнопка не заменяет серверную проверку прав.</p><label class="field">Пароль администратора<input type="password" class="input" id="adminPassword" autocomplete="current-password" maxlength="128"></label>${btn('adminLogin','Открыть панель','lock','primary')}<small class="dim">После 5 неверных попыток — пауза 30 секунд. Сессия длится 15 минут.</small></div>`;bind('#adminLogin',ev=>busy(ev.currentTarget,async()=>{S.admin=await call('adminLogin',$('#adminPassword',e).value);$('#adminPassword',e).value='';await renderAdmin();}),e);bind('#adminPassword',ev=>{if(ev.key==='Enter')$('#adminLogin',e).click();},e,'keydown');return;}
    e.innerHTML=head('Редактор новостей','Твои объявления для друзей.',btn('adminChange','Сменить пароль','lock')+btn('adminExit','Выйти','','ghost'))+`<div class="notice">${S.admin.mustChange?'<b>Рекомендуется сменить начальный пароль.</b><br>':''}Сохраняй новости как черновик или публикацию. Кнопка «Опубликовать ленту всем» отправляет все нечерновые публикации в подключённый GitHub. Без подключения работает только локальный экспорт.</div><div class="section-title"><h3>Мои публикации</h3><div class="row">${btn('adminExport','Экспорт ленты','upload')}${btn('newPost','Новая новость','plus','primary')}</div></div><div id="adminPosts" class="col"><div class="spinner"></div></div>`;
    bind('#adminExit',async()=>{await call('adminLogout');S.admin=null;renderAdmin();},e);bind('#adminChange',changePassword,e);bind('#adminExport',ev=>busy(ev.currentTarget,async()=>{if(await adminCall('adminExportNews'))toast('Лента сохранена. Передай fox-news.json друзьям.','ok');}),e);bind('#newPost',()=>postDialog(),e);
    adminExtras(e).catch(err=>toast(err.message,'err'));
    try{const posts=await adminCall('adminPosts');if(!$('#adminPosts',e))return;$('#adminPosts',e).innerHTML=posts.length?posts.map(p=>`<div class="card admin-list-row"><div class="list-copy"><b>${p.draft?'[Черновик] ':''}${p.pinned?'📌 ':''}${esc(p.title)}</b><div class="dim">${date(p.date)} · ${p.text.length} символов</div></div><button class="btn sm" data-postedit="${esc(p.id)}">Редактировать</button><button class="btn sm icon ghost danger" data-postdelete="${esc(p.id)}" title="Удалить">${icon('trash')}</button></div>`).join(''):empty('Пока нет своих новостей. Создай первую.','news');$$('[data-postedit]',e).forEach(b=>b.onclick=()=>postDialog(posts.find(p=>p.id===b.dataset.postedit)));$$('[data-postdelete]',e).forEach(b=>b.onclick=()=>confirm('Удалить новость?','При подключённом GitHub лента будет переопубликована без этой новости. Скачанные вручную файлы друзей не изменятся.',async()=>{const r=await adminCall('adminDeletePost',b.dataset.postdelete);toast(r.published?'Новость удалена, общая лента обновлена':r.error?'Удалено локально. GitHub не обновлён: '+r.error:'Новость удалена локально. GitHub не подключён.',r.error?'err':'ok');await loadNews();renderAdmin();},true));}catch(err){toast(err.message,'err');}}
  function postDialog(post){const m=modal(post?'Редактировать новость':'Новая новость',`<label class="field">Заголовок<input class="input" id="postTitle" maxlength="160" value="${esc(post?.title||'')}"></label><label class="field">Текст<textarea class="input" id="postText" rows="10" maxlength="50000" placeholder="Что нового в нашей сборке? Обычный текст, без HTML."></textarea></label><label class="field">Обложка — HTTPS-ссылка (необязательно)<input class="input" id="postImage" placeholder="https://…/image.png" value="${esc(post?.image||'')}"></label><label class="row"><input id="postPinned" type="checkbox" ${post?.pinned?'checked':''}> Закрепить сверху</label><label class="row"><input id="postDraft" type="checkbox" ${post?.draft?'checked':''}> Черновик — не показывать игрокам</label><p class="dim">После сохранения опубликуй ленту в GitHub кнопкой в панели.</p>`,[{text:'Отмена',run:m=>m.close()},{text:'Сохранить',primary:true,run:async m=>{const im=m.q('#postImage').value.trim();if(im&&!safeUrl(im))throw new Error('Обложка должна использовать HTTPS');await adminCall('adminSavePost',{...(post||{}),title:m.q('#postTitle').value,text:m.q('#postText').value,image:im,pinned:m.q('#postPinned').checked,draft:m.q('#postDraft').checked});await loadNews();m.close();renderAdmin();toast('Новость опубликована локально','ok');}}],true);m.q('#postText').value=post?.text||'';}
  function changePassword(){modal('Сменить пароль',`<label class="field">Текущий пароль<input class="input" id="oldPassword" type="password" autocomplete="current-password"></label><label class="field">Новый пароль (от 12 символов)<input class="input" id="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128"></label><label class="field">Повтори новый пароль<input class="input" id="repeatPassword" type="password" autocomplete="new-password" maxlength="128"></label>`,[{text:'Отмена',run:m=>m.close()},{text:'Сменить пароль',primary:true,run:async m=>{const p=m.q('#newPassword').value;if(p!==m.q('#repeatPassword').value)throw new Error('Пароли не совпадают');await adminCall('adminChangePassword',m.q('#oldPassword').value,p);S.admin=null;m.close();renderAdmin();toast('Пароль изменён. Войди снова.','ok');}}]);}
  // ---------- Fox Club: remote accounts, shop, holidays ----------
  const currencyName={foxes:'Фоксы 🦊',pumpkins:'тыквы 🎃',rubles:'учётные ₽'};
  const holidays={halloween:'Хеллоуин 🎃',newyear:'Новый год 🎄',winter:'Зимний фестиваль ❄',spring:'Праздник весны 🌷',summer:'Летний фестиваль ☀',birthday:'День рождения Fox 🎂',valentine:'День дружбы ♥'};
  let audio=null;
  function sound(kind='click'){if(S.settings.sounds===false||!S.settings.soundVolume)return;try{audio||=new AudioContext();audio.resume().catch(()=>{});const patterns={click:[{f:520,d:.045}],achievement:[{f:660,d:.10},{f:880,d:.13},{f:1100,d:.18}],error:[{f:220,d:.10},{f:165,d:.13}],launch:[{f:440,d:.08},{f:660,d:.12}],success:[{f:660,d:.08},{f:880,d:.12}]};let at=audio.currentTime;const vol=Math.min(.12,(+S.settings.soundVolume||.25)*.12);for(const note of (patterns[kind]||patterns.click)){const o=audio.createOscillator(),g=audio.createGain();o.type=kind==='achievement'?'triangle':'sine';o.frequency.setValueAtTime(note.f,at);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(vol,at+.012);g.gain.setTargetAtTime(.0001,at+note.d*.68,.025);o.connect(g).connect(audio.destination);o.start(at);o.stop(at+note.d);at+=note.d+.025;}}catch{}}
  document.addEventListener('click',ev=>{if(ev.target.closest('button'))sound();});
  function activeEvent(){return S.cloud?.events?.filter(e=>e.enabled&&Date.parse(e.starts_at)<=Date.now()&&Date.parse(e.ends_at)>Date.now()).sort((a,b)=>Date.parse(b.starts_at)-Date.parse(a.starts_at))[0];}
  function applyAppearance(){const a=/^#[\da-f]{6}$/i.test(S.settings.accent)?S.settings.accent:'#ff7a1a',style=document.documentElement.style;style.setProperty('--accent',a);style.setProperty('--accent2',a);style.setProperty('--accent3',a);style.setProperty('--accent-soft',a+'24');document.body.dataset.holiday=S.settings.eventTheme===false?'':activeEvent()?.theme||'';const badge=$('#eventBadge');if(badge){const e=activeEvent();badge.textContent=e?holidays[e.theme]||e.title:'';badge.title=e?'До '+new Date(e.ends_at).toLocaleString('ru-RU'):'';}}
  async function clubRefresh(){S.cloud=await call('cloudState');applyAppearance();renderAccountCard();syncRoleNav();return S.cloud;}
  function clubNotice(s){return `<div class="notice">${!s?.configured?'Fox Club пока недоступен. Играй в Minecraft — сборки и офлайн-аккаунты работают как обычно.':'Войди в аккаунт Fox в разделе «Аккаунты», чтобы получать награды и покупать подписки.'} Одиночная игра и серверы с офлайн-входом не требуют Fox Club.</div>`;}
  async function renderShop(){const e=$('#page-shop');e.innerHTML=head('Fox Store','Играй. Открывай достижения. Собирай свой стиль.')+'<div class="spinner"></div>';let s;try{s=await clubRefresh();}catch(err){e.innerHTML=head('Fox Store')+empty(esc(err.message));return;}
    const preview=[{id:'plus',title:'Fox Plus',description:'Редактор скинов и значок Plus. Первые 100 Фоксов — за час игры.',kind:'subscription',price:100,currency:'foxes',days:30,tier:1},{id:'pro',title:'Fox Pro',description:'Всё из Plus и значок Pro.',kind:'subscription',price:700,currency:'foxes',days:30,tier:2},{id:'exclusive',title:'Fox Exclusive',description:'Всё из Pro и эксклюзивный значок.',kind:'subscription',price:1500,currency:'foxes',days:30,tier:3}];
    const cat=s.catalog||preview,w=s.wallet;e.innerHTML=head('Fox Store','Без автосписаний. Выбирай срок от 1 до 24 месяцев.',btn('shopWallet','Кошелёк','box','primary')+btn('shopRefresh','Обновить','refresh'))+(w?(s.system_version===4?walletHero(s):`<div class="notice">Баланс: ${Number(w.foxes)} Фоксов. Для кошелька обнови SQL до 1.4.</div>`):clubNotice(s))+clubUpgrade(s)+`<div class="card promo-card"><h3>Промокод</h3><p class="dim">Промокод даёт скидку, авторский код дополнительно начисляет комиссию владельцу. Действует для покупок за Фоксы; один код — один раз на аккаунт.</p><div class="row wrap"><input class="input" id="shopPromoInput" maxlength=24 placeholder="Введи промокод" style="flex:1;min-width:180px" value="${esc(S.appliedPromo?.code||'')}"><button class="btn primary" id="shopPromoApply">Применить</button><button class="btn" id="shopPromoClear">Сбросить</button></div><p id="shopPromoStatus" class="dim">${S.appliedPromo?`Применён ${esc(S.appliedPromo.code)} · скидка ${Number(S.appliedPromo.discount_percent)}%`:''}</p></div><div class="section-title"><h3>Подписки Fox</h3></div>${paymentSwitch()}<div class="club-grid">${cat.filter(c=>c.kind==='subscription').sort((a,b)=>a.tier-b.tier||a.days-b.days).map(c=>productCard(c,s)).join('')}</div><div class="section-title"><h3>Аксессуары профиля и обмен валюты</h3></div><p class="dim">Только оформление лаунчера, не вещи персонажа Minecraft. Учётные рубли выдаёт владелец; настоящих платежей и вывода денег нет.</p><div class="club-grid">${cat.filter(c=>c.kind!=='subscription').map(c=>productCard(c,s)).join('')||empty('Каталог появится после подключения сервиса')}</div><div class="notice">Во время активного ивента: 1 тыква за каждые 5 минут игры с аккаунтом Fox и подключением к сервису. Вне ивента тыквы остаются на балансе, но ивент-товары закрыты. Начало и конец определяет владелец.</div>`;
    bind('#shopWallet',()=>nav('wallet'),e);bind('#shopRefresh',renderShop,e);bind('#shopPromoApply',async()=>{const code=$('#shopPromoInput',e).value.trim().toUpperCase();if(!/^[A-Z0-9_-]{3,24}$/.test(code))throw new Error('Код: 3–24 символа, латиница, цифры, _ или -');const result=await call('cloudAction','promo_validate',{code});S.appliedPromo={code,kind:result.kind,discount_percent:Number(result.discount_percent),commission_percent:Number(result.commission_percent||0),owner_nickname:result.owner_nickname||''};$('#shopPromoStatus',e).textContent=result.kind==='author'?`Авторский код ${code} · скидка ${Number(result.discount_percent)}% · автору ${Number(result.commission_percent||0)}%${result.owner_nickname?' ('+result.owner_nickname+')':''}`:`Промокод ${code} применён · скидка ${Number(result.discount_percent)}%`;toast('Промокод применён','ok');renderShop();},e);bind('#shopPromoClear',()=>{S.appliedPromo=null;renderShop();},e);bind('#shopTopUp',topUpPlaceholder,e);bindPurchases(e,cat,s,renderShop);bindPaySwitch(e,renderShop);bind('[data-wallet-topup]',()=>{},e);
  }
  function quoteFor(c,s){const rub=c.kind==='subscription'&&S.shopPay==='rubles';const q=(rub?s.quotes_rub:s.quotes)?.find(q=>q.product===c.id);return {...(q||{price:c.price,mode:'buy'}),available:!rub||!!q,pay_in:rub?'rubles':'foxes',displayPrice:rub?(q?rubles(q.price):'Не настроено'):Number(q?.price??c.price),currencyLabel:rub?'':currencyName[c.currency],basePrice:rub?Number(c.price_kopeks||0)/100:Number(c.price)};}

  function bindPurchases(e,cat,s,refresh){$$('[data-buy]',e).forEach(b=>bind('[data-buy="'+b.dataset.buy+'"]',()=>{const c=cat.find(c=>c.id===b.dataset.buy),q=quoteFor(c,s),upgrade=q.mode==='upgrade',purchaseRequest=crypto.randomUUID();confirm((upgrade?'Улучшить до ':'Купить ')+c.title+'?',`${q.displayPrice} ${q.currencyLabel}. ${c.kind==='subscription'?upgrade?'Старая подписка заменится новой. Оставшиеся дни сохранятся, добавится ещё '+c.days+' дней.':q.mode==='renew'?'Продление на '+c.days+' дней.':'На '+c.days+' дней.':''} ${c.kind==='case'?'Один случайный аксессуар из ещё не полученных. Без повторов и обмена на деньги.':''} Цена и скидка проверяются сервером.`,async()=>{const promo=(q.pay_in==='foxes'?S.appliedPromo:null);const expected=promo?Math.floor(Number(q.price)*(100-Number(promo.discount_percent))/100):Number(q.price);const response=await call('cloudAction','buy',{product:c.id,expected_price:expected,pay_in:q.pay_in,request_id:purchaseRequest,promo_code:promo?.code||null});S.cloud={configured:true,...response};sound('achievement');renderAccountCard();if(response.last_drop){const drop=response.catalog.find(x=>x.id===response.last_drop);modal('Кейс открыт',`<div class="drop-reveal">${cosmeticInfo(response.last_drop)?.symbol||'✨'}<h2>${esc(drop?.title||'Аксессуар')}</h2><p>Добавлен в коллекцию Fox.</p></div>`,[{text:'К коллекции',primary:true,run:m=>{m.close();nav('achievements');}}]);}await refresh();});},e));}
  function productCard(c,s){const q=quoteFor(c,s),promo=(q.pay_in==='foxes'?S.appliedPromo:null),shownPrice=promo?Math.floor(Number(q.price)*(100-Number(promo.discount_percent))/100):Number(q.price),subscription=c.kind==='subscription',unsupported=subscription&&s.profile&&s.shop_version!==3,blocked=q.mode==='blocked',upgrade=q.mode==='upgrade';const remaining=c.id==='style-case'?['fox-hat','night-cape','star-art'].filter(id=>!s.purchases?.some(p=>p.product_id===id)).length:null,exhausted=remaining===0,owned=c.kind==='cosmetic'&&s.purchases?.some(p=>p.product_id===c.id),locked=c.event_only&&!activeEvent();return `<article class="card club-product tier-${Number(c.tier)||0}"><span class="tag accent">${upgrade?'УЛУЧШЕНИЕ':subscription?'ПОДПИСКА':c.event_only?'ИВЕНТ':'КОЛЛЕКЦИЯ'}</span><h2>${esc(c.title)}</h2><p class="muted">${esc(c.description)}</p>${remaining!==null?`<p class="dim">${exhausted?'Коллекция собрана':`Осталось: ${remaining}. Шанс каждого: ${(100/remaining).toLocaleString('ru-RU',{maximumFractionDigits:2})}%.`}</p>`:''}${upgrade?`<p class="dim">Скидка апгрейда: ${Number(s.upgrade_discount)}%. Остаток дней сохранится.</p>`:''}${Number(c.discount_percent)>0?`<span class="tag accent">Скидка ${Number(c.discount_percent)}%</span>`:''}<div class="grow"></div><strong class="club-price">${q.available&&Number(q.price)<(q.pay_in==='rubles'?Number(c.price_kopeks):Number(c.price))?`<span class="price-before">${q.basePrice}</span> `:''}${shownPrice} <small>${q.currencyLabel}</small>${promo?` <span class="price-before">${q.displayPrice}</span><span class="tag accent">−${Number(promo.discount_percent)}%</span>`:''}</strong><button class="btn primary" data-buy="${esc(c.id)}" ${!s.wallet||owned||locked||exhausted||blocked||unsupported||!q.available?'disabled':''}>${!q.available?'Цена пока не задана':unsupported?'Обнови SQL до 1.3':blocked?'У тебя подписка выше':exhausted?'Коллекция собрана ✓':owned?'Куплено ✓':locked?'Ивент не активен':upgrade?'Улучшить':q.mode==='renew'?'Продлить':c.kind==='case'?'Открыть кейс':'Купить'}</button></article>`;}
  async function renderSubscription(){const e=$('#page-subscription');e.innerHTML=head('Моя подписка')+'<div class="spinner"></div>';const s=await clubRefresh(),a=s.active_subscription,cat=(s.catalog||[]).filter(c=>c.kind==='subscription').sort((a,b)=>a.tier-b.tier||a.days-b.days);e.innerHTML=head('Моя подписка','Без автосписаний.',btn('subRefresh','Обновить','refresh'))+(!s.profile?clubNotice(s):s.shop_version!==3?'<div class="notice">Владельцу нужно выполнить backend/migrate-1.3.sql поверх базы 1.2.</div>':`<div class="card"><span class="tag accent">${a?'АКТИВНА':'БЕЗ ПОДПИСКИ'}</span><h2>${esc(a?.title||'Бесплатный Fox Club')}</h2><p>${a?'Действует до '+esc(new Date(a.expires_at).toLocaleString('ru-RU')):'Можно выбрать подписку ниже.'}</p><p class="dim">${a?'Улучшение заменяет старый тариф: остаток дней сохраняется + 30 новых дней. Скидка улучшения '+Number(s.upgrade_discount)+'%. Продление добавляет выбранный срок. Более низкий тариф до окончания недоступен.':'Выбирай оплату Фоксами или с рублёвого баланса.'}</p><b>Баланс: ${Number(s.wallet?.foxes||0)} Фоксов · ${rubles(s.wallet?.paid_kopeks)}</b></div>`)+`<div class="section-title"><h3>Доступные тарифы</h3></div>${paymentSwitch()}<div class="club-grid">${cat.map(c=>productCard(c,s)).join('')}</div>`;bind('#subRefresh',renderSubscription,e);bindPurchases(e,cat,s,renderSubscription);bindPaySwitch(e,renderSubscription);}
  async function showPlayer(data){const p=await call('cloudAction','player_profile',data),c=cosmeticInfo(p.equipped_cosmetic);modal('Профиль игрока',`<div class="card collection-profile" data-cosmetic="${c?esc(p.equipped_cosmetic):''}"><span class="collection-symbol">${c?.symbol||'🦊'}</span><div><h2>${esc(p.nickname)}</h2><p>${esc(p.subscription?.title||'Fox Club')}</p><small class="dim">В Fox с ${date(p.created_at)}</small></div></div>${roleTags(p.roles)}<p class="muted" style="margin:14px 0">${esc(p.about||'')}</p>${p.stats_hidden?'<div class="notice">Статистика скрыта настройками игрока.</div>':`<div class="wallet-row"><div class="card"><small>В игре</small><h2>${hours(Number(p.seconds)*1000)}</h2></div><div class="card"><small>Уровень</small><h2>${Number(p.level?.level)||1}</h2></div><div class="card"><small>Квестов</small><h2>${Number(p.quests)}</h2></div></div><h3>Достижения</h3><div class="achievement-badges">${(p.achievements||[]).map(code=>`<div class="achievement-badge" title="${esc(({gamer:'Геймер',addict:'Игроман',first30:'Первые полчаса',explorer3:'Три мира',veteran25:'Ветеран',quests10:'Охотник за квестами',quests30:'Мастер заданий'})[code]||code)}"><img src="../assets/achievements/${esc(code)}.svg" alt="${esc(({gamer:'Геймер',addict:'Игроман',first30:'Первые полчаса',explorer3:'Три мира',veteran25:'Ветеран',quests10:'Охотник за квестами',quests30:'Мастер заданий'})[code]||code)}"><span>${esc(({gamer:'Геймер',addict:'Игроман',first30:'Первые полчаса',explorer3:'Три мира',veteran25:'Ветеран',quests10:'Охотник за квестами',quests30:'Мастер заданий'})[code]||code)}</span></div>`).join('')||'Пока нет достижений'}</div>`}${Array.isArray(p.friends)?`<h3 style="margin-top:16px">Друзья</h3><p>${p.friends.map(f=>esc(f.nickname)).join(', ')||'Пока нет друзей'}</p>`:''}<p class="dim" style="margin-top:16px">${esc(c?.label||'Без аксессуара')} · оформление Fox Launcher. Почта, кошелёк и обращения скрыты.</p>`,[{text:'Закрыть',run:m=>m.close()},...(!p.self&&p.public_key?[{text:'Добавить в друзья',primary:true,run:async m=>{await call('cloudAction','friend_request',{key:p.public_key});toast('Заявка отправлена','ok');m.close();}}]:[])]);}
  let playersRequest=0;
  async function renderPlayers(){const e=$('#page-players');e.innerHTML=head('Профили игроков','Найди друзей по игровому нику.')+`<div class="notice">Здесь видны только игроки, включившие публичность в разделе «Топ игроков». Email, Fox ID и история операций не публикуются.</div><form id="playersForm" class="players-search"><label class="field" for="playerSearch">Поиск по нику<div class="search">${icon('search')}<input class="input" id="playerSearch" placeholder="Начало ника" maxlength="16" autocomplete="off"></div></label><button class="btn primary" type="submit">${icon('search')}Найти игроков</button></form><div id="playersRows" class="player-grid" aria-live="polite" aria-busy="false"></div>`;async function load(){const request=++playersRequest,rows=$('#playersRows',e);rows.setAttribute('aria-busy','true');rows.innerHTML='<div class="spinner"></div>';try{const items=await call('cloudAction','players',{search:$('#playerSearch',e).value.trim()});if(request!==playersRequest||!rows.isConnected)return;rows.innerHTML=items.map(p=>`<button type="button" class="card player-open" data-profile-key="${esc(p.public_key)}"><span class="player-avatar" aria-hidden="true">${cosmeticInfo(p.equipped_cosmetic)?.symbol||'🦊'}</span><span class="player-info"><b>${esc(p.nickname)}</b><small>Открыть профиль</small></span>${icon('back')}</button>`).join('')||empty('Публичные профили не найдены');$$('[data-profile-key]',rows).forEach(b=>bind('[data-profile-key="'+b.dataset.profileKey+'"]',()=>busy(b,()=>showPlayer({key:b.dataset.profileKey})),rows));}catch(err){if(request===playersRequest)rows.innerHTML=empty(esc(err.message)+' · Для новых функций нужен backend/migrate-1.3.sql.');}finally{if(request===playersRequest)rows.setAttribute('aria-busy','false');}}bind('#playersForm',ev=>{ev.preventDefault();return load();},e,'submit');await load();}

