  function collectionMarkup(s){const owned=(s.purchases||[]).filter(p=>(s.catalog||[]).find(c=>c.id===p.product_id)?.kind==='cosmetic');const unique=[...new Set(owned.map(p=>p.product_id))];return `<div class="section-title"><h3>Коллекция профиля</h3></div><p class="dim">Шапки, плащи и рисунки — оформление карточки Fox, не предметы Minecraft. Выбери один аксессуар.</p>${s.profile?`<div class="card collection-profile" data-cosmetic="${cosmeticInfo(s.profile.equipped_cosmetic)?esc(s.profile.equipped_cosmetic):''}"><span class="collection-symbol">${cosmeticInfo(s.profile.equipped_cosmetic)?.symbol||'🦊'}</span><div><h2>${esc(s.profile.nickname)}</h2><p class="dim">${esc(cosmeticInfo(s.profile.equipped_cosmetic)?.label||'Без аксессуара')}</p></div>${s.profile.equipped_cosmetic&&s.club_version===2?'<button class="btn sm" data-equip="">Снять</button>':''}</div><div class="club-grid">${unique.map(id=>{const c=s.catalog.find(x=>x.id===id),active=s.profile.equipped_cosmetic===id;return `<article class="card club-product"><span class="collection-symbol">${cosmeticInfo(id)?.symbol||'✨'}</span><h2>${esc(c.title)}</h2><p class="muted">${esc(c.description)}</p><button class="btn ${active?'':'primary'}" data-equip="${esc(id)}" ${active||s.club_version!==2?'disabled':''}>${active?'Надето ✓':'Надеть'}</button></article>`;}).join('')||empty('Полученные аксессуары появятся здесь.')}</div>`:clubNotice(s)}`;}
