    e.innerHTML=head('Задания и достижения','Небольшая цель сегодня — большое приключение завтра.',btn('tasksBack','Достижения','award')+btn('questsRefresh','Обновить','refresh'))+(!s.profile?clubNotice(s):clubUpgrade(s))+`<article class="card daily-card"><div><span class="tag accent">ЕЖЕДНЕВНЫЙ ПОДАРОК</span><h2>+${Number(d.reward)||25} Фоксов</h2><p>Серия: ${Number(d.streak)||0} / 7. Каждый день подряд +5 Фоксов, максимум 55.</p><small class="dim">После пропуска серия начинается заново. Сброс в 00:00 UTC.${d.next_reset?' У тебя: '+esc(new Date(d.next_reset).toLocaleString('ru-RU')):''}</small></div><button class="btn primary" id="dailyClaim" ${!ready||d.claimed?'disabled':''}>${d.claimed?'Сегодня получено ✓':'Забрать подарок'}</button></article><div class="notice">Квесты считают только время онлайн-сессий Fox после входа. Меню и AFK учитываются. Для квеста со сборками нужно провести в каждой хотя бы один учтённый интервал. Дневной прогресс начинается после обновления SQL; старое локальное время не переносится.</div><div class="section-title"><h3>Сегодня · обновление в 00:00 UTC</h3></div><div class="club-grid">${quests.filter(q=>q.scope==='daily').map(card).join('')}</div><div class="section-title"><h3>На неделю · сброс в понедельник, 00:00 UTC</h3></div><div class="club-grid">${quests.filter(q=>q.scope==='weekly').map(card).join('')}</div><div class="section-title"><h3>Большие цели · один раз на аккаунт</h3></div><div class="club-grid">${quests.filter(q=>q.scope==='career').map(card).join('')}</div>`;
    bind('#tasksBack',renderAchievements,e);bind('#questsRefresh',renderQuests,e);bind('#dailyClaim',()=>busy($('#dailyClaim',e),async()=>{S.cloud={configured:true,...await call('cloudAction','daily_claim')};sound('achievement');toast('Ежедневная награда получена','ok');await renderQuests();}),e);
    $$('[data-claim-quest]',e).forEach(b=>b.addEventListener('click',async()=>{try{await busy(b,async()=>{S.cloud={configured:true,...await call('cloudAction','quest_claim',{quest:b.dataset.claimQuest})};sound('achievement');toast('Награда за квест получена','ok');await renderQuests();});}catch(err){toast(err.message,'err');}}));
