    bind('#leadersRefresh',renderLeaderboards,e);$$('[data-leader-metric]',e).forEach(b=>b.onclick=()=>{S.leaderboardMetric=b.dataset.leaderMetric;renderLeaderboards().catch(err=>toast(err.message,'err'));});
    bind('#leaderVisibility',async()=>{const input=$('#leaderVisibility',e);input.disabled=true;try{S.cloud={configured:true,...await call('cloudAction','profile_visibility',{visible:input.checked})};await renderLeaderboards();}catch(err){input.checked=!input.checked;throw err;}finally{if(input.isConnected)input.disabled=false;}},e,'change');
