    try{const board=await call('cloudAction','leaderboard',{metric});if(request!==leaderboardRequest)return;const score=n=>metric==='playtime'?hours(Number(n)*1000):Number(n).toLocaleString('ru-RU');$('#leaderRows',e).innerHTML=`<p class="dim">Участников: ${Number(board.participants)}. Квесты учитываются после получения награды.</p>${board.self?`<div class="notice">Твоё место: #${Number(board.self.place)} · ${score(board.self.score)}</div>`:'<p class="dim">Твой профиль скрыт. Включи участие, чтобы попасть в топ.</p>'}<div class="leader-table" role="table" aria-label="${esc(metrics[metric])}"><div class="leader-row leader-header" role="row"><span role="columnheader">Место</span><span role="columnheader">Аккаунт Fox</span><span role="columnheader">${esc(metrics[metric])}</span></div>${board.items.map(row=>`<div class="leader-row ${row.self?'is-self':''}" role="row"><b role="cell">#${Number(row.place)}</b><span role="cell">${cosmeticInfo(row.equipped_cosmetic)?.symbol||'🦊'} <button class="btn sm ghost" data-profile-name="${esc(row.nickname)}">${esc(row.nickname)}</button> ${row.self?'<span class="tag accent">ТЫ</span>':''}</span><strong role="cell">${score(row.score)}</strong></div>`).join('')||empty('Пока нет участников. Можно стать первым!')}</div>`;}catch(err){if(request===leaderboardRequest)$('#leaderRows',e).innerHTML=empty(esc(err.message));}
