  async function renderAchievements(){const e=$('#page-achievements');e.innerHTML=head('Достижения','Каждый мир — часть твоей истории.')+'<div class="spinner"></div>';const local=await call('getPlaytime');let s;try{s=await clubRefresh();}catch{s={};}const times=s.progress?.map(x=>Number(x.seconds)*1000)||Object.values(local.instances),total=times.reduce((a,b)=>a+b,0),max=Math.max(0,...times),unlocked=new Set(s.achievements?.map(x=>x.code)||local.achievements);e.innerHTML=head('Задания и достижения','Время считается, пока работает процесс игры; меню и AFK тоже учитываются.',btn('tasksOpen','Квесты и награды','check')+btn('achRefresh','Обновить','refresh'))+(!s.profile?clubNotice(s):`<div class="notice">Награды начисляются один раз на аккаунт Fox. В зачёт идут онлайн-сессии после входа, без переноса старого локального времени.</div>`)+`<div class="club-grid">${[['gamer','Геймер',total,3600000,'1 час за всё время','100 Фоксов'],['addict','Игроман',max,36000000,'10 часов на одной сборке','500 Фоксов'],['first30','Первые полчаса',total,1800000,'30 минут за всё время','50 Фоксов'],['explorer3','Три мира',(s.progress||[]).filter(p=>Number(p.seconds)>0).length,3,'Поиграть на трёх сборках','100 Фоксов'],['veteran25','Ветеран',total,90000000,'25 часов за всё время','300 Фоксов'],['quests10','Охотник за квестами',Number(s.level?.xp||0)-Math.floor(total/60000),500,'Получить 10 наград за квесты','200 Фоксов'],['quests30','Мастер заданий',Number(s.level?.xp||0)-Math.floor(total/60000),1500,'Получить 30 наград за квесты','500 Фоксов']].map(([id,title,n,target,desc,reward])=>`<article class="card club-product"><span class="tag ${unlocked.has(id)?'accent':''}">${unlocked.has(id)?'ОТКРЫТО ✓':'В ПРОЦЕССЕ'}</span><h2>${title}</h2><p>${desc}</p><div class="club-progress"><i style="width:${Math.min(100,n/target*100)}%"></i></div><div class="muted">${id==='explorer3'?n+' / '+target+' сборок':id.startsWith('quests')?Math.floor(n/50)+' / '+target/50+' квестов':hours(n)+' / '+hours(target)}</div><b>Награда: ${reward}</b>${!s.profile?'<small class="dim">Локальное достижение не начисляет облачную валюту.</small>':''}</article>`).join('')}</div>${collectionMarkup(s)}`;bind('#tasksOpen',renderQuests,e);bind('#achRefresh',renderAchievements,e);bindCollection(e);}
